INSERT INTO especialidades (nombre, descripcion) VALUES 
('Medicina General', 'Atención primaria y prevención en salud.'),
('Pediatría', 'Atención médica especializada en niños y adolescentes.'),
('Cardiología', 'Estudio, diagnóstico y tratamiento de las enfermedades del corazón.'),
('Oncología', 'Estudio y tratamiento de los tumores benignos y malignos.'),
('Dermatología', 'Diagnóstico y tratamiento de las afecciones de la piel, mucosas, pelo y uñas.'),
('Traumatología', 'Tratamiento de lesiones del sistema musculoesquelético, huesos y articulaciones.'),
('Ginecología y Obstetricia', 'Atención integral de la salud sexual y reproductiva de la mujer y del embarazo.'),
('Oftalmología', 'Diagnóstico y tratamiento de enfermedades de los ojos y la visión.'),
('Neurología', 'Estudio y tratamiento de trastornos del sistema nervioso.'),
('Psiquiatría', 'Atención de la salud mental, prevención y tratamiento de trastornos psicológicos.'),
('Otorrinolaringología', 'Tratamiento de afecciones del oído, nariz y garganta.'),
('Odontología', 'Tratamiento y cuidado de la salud dental y bucal.');
