INSERT INTO historia_clinica (id_paciente, id_medico, id_cita, motivo_consulta, diagnostico, observaciones) VALUES 
(1, 1, 1, 'Control general de rutina.', 'Paciente sano, sin patologías aparentes.', 'Se aconseja mantener hábitos de vida saludables y actividad física regular.'),
(2, 5, 2, 'Revisión pediátrica mensual.', 'Desarrollo psicomotor adecuado para la edad.', 'Ganancia de peso y talla dentro de los percentiles normales.'),
(3, 7, 3, 'Dolor en el pecho leve.', 'Angina de pecho estable inicial.', 'Se solicita electrocardiograma de control y valoración por cardiología avanzada.'),
(4, 2, 4, 'Exámenes de laboratorio preventivos.', 'Perfil lipídico alterado (colesterol levemente elevado).', 'Se recomienda dieta baja en grasas y caminatas diarias de 30 minutos.'),
(5, 8, 5, 'Consulta inicial de oncología.', 'Evaluación preventiva de antecedentes familiares.', 'Sin hallazgos tumorales palpables. Se programan marcadores tumorales preventivos.'),
(6, 9, 6, 'Control por dermatitis atópica.', 'Dermatitis seborreica leve en cuero cabelludo.', 'Se receta crema tópica y champú especializado.'),
(7, 11, 7, 'Dolor articular en rodilla derecha.', 'Principio de desgaste meniscal leve.', 'Evitar impacto fuerte y realizar sesiones de fisioterapia.'),
(8, 12, 8, 'Control prenatal.', 'Embarazo de 20 semanas en curso, evolución normal.', 'Se indican vitaminas prenatales y ecografía morfológica de control.'),
(9, 13, 9, 'Examen de agudeza visual.', 'Miopía leve en ambos ojos.', 'Se formula corrección con lentes ópticados de descanso.'),
(10, 15, 10, 'Evaluación por cefalea frecuente.', 'Cefalea tensional asociada a estrés laboral.', 'Se sugiere manejo de pausas activas, descanso adecuado y analgésico SOS.'),
(11, 16, 11, 'Seguimiento psiquiátrico.', 'Trastorno de ansiedad generalizada controlado.', 'Paciente refiere mejoría con el tratamiento farmacológico actual. Continuar dosis.'),
(12, 19, 12, 'Infección recurrente de oídos.', 'Otitis externa leve en oído izquierdo.', 'Se recetan gotas óticas antibióticas por 7 días y evitar ingreso de agua.'),
(13, 20, 13, 'Limpieza dental y revisión general.', 'Sarro leve en piezas inferiores y encías sanas.', 'Realizada profilaxis dental sin complicaciones. Control en 6 meses.'),
(14, 3, 14, 'Chequeo de presión arterial.', 'Hipertensión arterial estadio 1.', 'Se inicia tratamiento con antihipertensivo de baja dosis y control en un mes.'),
(15, 6, 15, 'Vacunación y control de crecimiento.', 'Esquema de vacunación al día.', 'Paciente activo, reactivo y con adecuada evolución ponderal.'),
(16, 10, 16, 'Revisión de lunares sospechosos.', 'Nevo melanocítico benigno sin signos de displasia.', 'Se aconseja protección solar permanente y vigilancia visual de cambios.'),
(17, 14, 17, 'Formulación de lentes.', 'Astigmatismo miópico compuesto.', 'Se emite fórmula médica para anteojos definitivos.'),
(18, 17, 18, 'Consulta de control por ansiedad.', 'Episodio ansioso reactivo transitorio.', 'Se brindan pautas de manejo respiratorio y apoyo psicológico breve.'),
(19, 21, 19, 'Dolor muela del juicio.', 'Pericoronaritis en tercer molar inferior derecho.', 'Se prescribe analgésico/antiinflamatorio y se remite para extracción quirúrgica.'),
(20, 4, 20, 'Malestar general y fiebre.', 'Infección respiratoria aguda alta (resfriado común).', 'Reposo domiciliario, hidratación abundante y acetaminofén según necesidad.'),
(21, 18, 21, 'Evaluación de trastornos del sueño.', 'Insomnio secundario a hábitos de higiene del sueño inadecuados.', 'Se establecen pautas de desconexión nocturna y control en tres semanas.'),
(22, 22, 22, 'Instalación de ortodoncia básica.', 'Maloclusión dental clase I.', 'Se colocan bandas y arcos iniciales superiores.'),
(23, 1, 23, 'Renovación de incapacidad médica.', 'Lumbalgia mecánica inespecífica.', 'Se extiende incapacidad por 3 días más y se pauta manejo con relajantes musculares.'),
(24, 5, 24, 'Control de peso y talla en menores.', 'Curva de crecimiento estacionaria.', 'Se refuerza asesoría nutricional con pediatría y complementos vitamínicos.'),
(25, 7, 25, 'Electrocardiograma de rutina.', 'Ritmo sinusal normal sin alteraciones isquémicas.', 'Corazón estructuralmente sano. No requiere medicamentos.'),
(26, 12, 26, 'Ecografía obstétrica de control.', 'Feto único activo con frecuencia cardíaca normal.', 'Todo marcha excelente. Próximo control en un mes.'),
(27, 15, 27, 'Seguimiento neurológico.', 'Migraña con aura estable.', 'Sin episodios críticos recientes. Se mantiene medicación preventiva.'),
(28, 20, 28, 'Tratamiento de caries.', 'Caries oclusal en molar inferior izquierdo.', 'Realizada obturación con resina fotopolimerizable con éxito.'),
(29, 3, 29, 'Examen físico anual obligatorio.', 'Examen físico sin alteraciones significativas.', 'Recomendaciones de estilo de vida saludable y chequeo general al próximo año.'),
(30, 9, 30, 'Tratamiento para alergia cutánea.', 'Urticaria alérgica de contacto leve.', 'Se prescribe antihistamínico oral y evitar exposición al agente irritante.');
